package com.elker54.tetraalert

import org.junit.Assert.assertEquals
import org.junit.Test

/** Byte vectors generated by tetra_link.py on the Pi side. */
class LinkTest {
    private fun hex(s: String) = s.chunked(2).map { it.toInt(16).toByte() }.toByteArray()
    private fun ByteArray.toHex() = joinToString("") { "%02x".format(it) }

    @Test fun alert() {
        val a = Link.parseAlert(hex("010202cdfd04e8e816"))!!
        assertEquals(Link.Alert(513, 2, -56.3, 384_362_500L), a)
    }

    @Test fun status() {
        val s = Link.parseStatus(hex("0700013d4505efbeadde"))!!
        assertEquals(Link.Status(7, 1, 61, 69, 5, 0xDEADBEEFL), s)
    }

    @Test fun shutdownToken() {
        assertEquals("53444d11952d0f1f4226", Link.shutdownToken("1234", 0x01020304L).toHex())
        assertEquals("5344d7559ceaa6c84642", Link.shutdownToken("4821", 0xDEADBEEFL).toHex())
    }

    @Test fun packTime() {
        assertEquals("7bd406ffa1010000", Link.packTime(1_795_280_000_123L).toHex())
    }

    @Test fun wifiOnToken() {
        assertEquals("574914c6908309120d73", Link.wifiOnToken("1234", 0x01020304L).toHex())
    }

    @Test fun filesRequest() {
        assertEquals("47fbb19d47aad8d7f7" + "live_car_1".toByteArray().toHex(),
            Link.filesRequest("1234", 'G', "live_car_1", 0x01020304L).toHex())
    }

    @Test fun reassemble() {
        val r = Link.Reassembler()
        assertEquals(Link.Reassembler.Step.PROGRESS, r.add(hex("484c0b00000085114a0d")))
        assertEquals(Link.Reassembler.Step.DONE, r.add(hex("4468656c6c6f20776f726c64")))
        assertEquals('L', r.kind)
        assertEquals("hello world", String(r.payload))
        val bad = Link.Reassembler()
        bad.add(hex("484c0b00000085114a0d"))
        assertEquals(Link.Reassembler.Step.BAD, bad.add(hex("4468656c6c6f20776f726c65")))
    }

    @Test fun historyLine() {
        val e = AlertLog.Entry(1_795_280_000_123L, 2, 56.3, 384_362_500L, 51.4769, -0.0005, 12f)
        assertEquals(e, AlertLog.parse(AlertLog.format(e)))
        val n = e.copy(lat = null, lon = null, accM = null)
        assertEquals(n, AlertLog.parse(AlertLog.format(n)))
        val saw = AlertLog.Entry(1_795_280_000_123L, AlertLog.SIGHTING, 0.0, 0L, 51.4769, -0.0005, 8f)
        assertEquals(saw, AlertLog.parse(AlertLog.format(saw)))
    }

    @Test fun live() {
        // tetra_link.pack_live(2, 56.3, 384362500) = 02330204e8e816
        val l = Link.parseLive(hex("02330204e8e816"))!!
        assertEquals(2, l.tone); assertEquals(56.3, l.db, 0.01); assertEquals(384_362_500L, l.freqHz)
    }
}
